/bin/zsh -lc "apply_patch <<'PATCH'
*** Begin Patch
*** Update File: TopModule.sv
@@
 	reg [8:0] a_tem;
 	reg match_f;
 	reg match_b;
+	wire [8:0] a_next;
+
+	assign a_next = {a_tem[7:0], a};

 	always @(posedge clk or negedge rst_n)
 		if ("'!rst_n)
 			begin 
 				match_f <= 1'"'b0;
 			end
-		else if (a_tem[8:6] == 3'b011)
+		else if (a_next[8:6] == 3'b011)
 			begin
 				match_f <= 1'b1;
 			end
@@
 	always @(posedge clk or negedge rst_n)
 		if ("'!rst_n)
 			begin 
 				match_b <= 1'"'b0;
 			end
-		else if (a_tem[2:0] == 3'b110)
+		else if (a_next[2:0] == 3'b110)
 			begin
 				match_b <= 1'b1;
 			end
@@
 		else 
 			begin
-				a_tem <= {a, a_tem[7:0]};
+				a_tem <= a_next;
 			end
*** End Patch
PATCH

cat > tb.sv <<'EOF'
module tb;
  reg clk = 0;
  reg rst_n = 0;
  reg a = 0;
  wire match;

  TopModule dut (
    .clk(clk),
    .rst_n(rst_n),
    .a(a),
    .match(match)
  );

  always #5 clk = ~clk;

  task send_bit(input reg bitval);
    begin
      a = bitval;
      @(posedge clk);
      #1;
      "'$display("t=%0t a=%0b shift=%09b match=%0b", $time, a, dut.a_tem, match);
    end
  endtask

  initial begin
    repeat (2) @(posedge clk);
    rst_n = 1;

    send_bit(0);
    send_bit(1);
    send_bit(1);
    send_bit(0);
    send_bit(0);
    send_bit(1);
    send_bit(1);
    send_bit(1);
    send_bit(0);

    if (match !== 1'"'b1) begin
      "'$display("FAIL: expected match after 011xxx110");
      $finish_and_return(1);
    end

    send_bit(1);
    if (match !== 1'"'b0) begin
      "'$display("FAIL: expected match to drop for non-matching window");
      $finish_and_return(1);
    end

    $display("PASS");
    $finish;
  end
endmodule
EOF

iverilog -g2012 -o simv TopModule.sv tb.sv && vvp simv'

